if(f.id==='erp-credential-form'){let erp=data.erps.find(e=>e.id===id);if(!erp)return;let selectedDomains=v.getAll('dataDomains').filter(domain=>ERP_DATA_DOMAINS.includes(domain));if(!selectedDomains.length){toast('请至少选择一个数据领域');f.querySelector('[name=dataDomains]')?.focus();return}if(!v.get('appId')?.trim()||!v.get('appSecret')?.trim()){toast('请完整填写 AppID 和 AppSecret');return}if(f.dataset.tested!=='true'){toast('请先检查填写');return}erp.credentialConfigured=true;erp.authMethod='AppID + AppSecret';erp.credentialUpdated=new Date().toLocaleString('zh-CN');erp.state='已授权';erp.last=erp.last==='—'?'等待首次同步':erp.last;erp.dataDomains=selectedDomains;erp.scope=selectedDomains.join('、');erp.stores=erp.id==='saihu'?['待识别店铺']:['北美旗舰店','欧洲精品店'];save();close();toast('连接器配置已保存（演示）；凭据未保存，未连接真实 ERP');return}
if(f.id==='erp-domains-form'){let erp=data.erps.find(e=>e.id===id);if(!erp||erp.state!=='已授权'){toast('仅已授权连接器可调整数据配置');return}let selectedDomains=v.getAll('dataDomains').filter(domain=>ERP_DATA_DOMAINS.includes(domain));if(!selectedDomains.length){toast('请至少选择一个数据领域');f.querySelector('[name=dataDomains]')?.focus();return}erp.dataDomains=selectedDomains;erp.scope=selectedDomains.join('、');save();close();toast('数据配置已更新（演示）');return}
if(f.id==='agent-form'){let a=data.agents.find(x=>x.id===id),types=v.getAll('inputType'),labels=v.getAll('inputLabel'),keys=v.getAll('inputKey'),requirements=v.getAll('inputRequired');if(!types.length){toast('请至少配置一个输入参数');return}if(types.filter(type=>type==='store-multi').length>1||types.filter(type=>type==='product-multi').length>1){toast('内置店铺和产品参数各只能添加一次');return}let params=types.map((type,i)=>({key:type==='store-multi'?'stores':type==='product-multi'?'products':keys[i]&&keys[i]!=='stores'&&keys[i]!=='products'?keys[i]:`custom-${Date.now()}-${i}`,label:type==='store-multi'?'店铺':type==='product-multi'?'产品':String(labels[i]||'').trim(),type,required:requirements[i]==='yes'}));if(params.some(param=>!param.label)){toast('请填写自定义参数名称');return}if(params.some(param=>!['store-multi','product-multi','text','number','date'].includes(param.type))){toast('存在不支持的参数类型');return}preserveLive(a);a.name=v.get('name').trim();a.scope=v.get('scope').trim();a.role=v.get('role').trim();a.skill=v.get('skill').trim();a.inputParams=params;a.knowledge=v.getAll('knowledge');a.employees=v.getAll('employees');a.draftNote=v.get('draftNote').trim();a.checks=false;a.tested=false;if(!a.live)a.status='草稿';save();render();toast('草稿已保存，需重新检查并发布');return}
if(f.id==='create-agent-form'){let n=data.agents.length+1,a={id:'a'+Date.now(),name:v.get('name').trim(),kind:'企业私有',icon:'◈',scope:v.get('scope').trim(),role:v.get('role').trim(),skill:'',skillVersion:'v0.1',inputParams:[{key:'stores',label:'店铺',type:'store-multi',required:true}],knowledge:[],erp:'领星 ERP',stores:['北美旗舰店'],model:data.models[0]?.name||'未配置',tools:[],employees:['张管理员'],status:'草稿',version:'v0.1',tested:false,checks:false,last:'今日',subscription:'自建',draftNote:''};data.agents.push(a);save();modal=null;go('agent',a.id);toast('私有 Agent 草稿已创建');return}
if(f.id==='confirm-form'){let r=data.runs.find(x=>x.id===id),decision=v.get('decision'),qty=+v.get('quantity'),note=v.get('note').trim();if(decision!=='接受'&&!note){toast('修改或驳回时请填写处理说明');return}if(decision==='修改后接受'&&(!Number.isFinite(qty)||qty<0)){toast('请填写有效的最终数量');return}r.decision=decision;r.state=decision==='驳回'?'已驳回':'已接受';r.final=decision==='驳回'?0:decision==='接受'?r.suggested:qty;r.confirmNote=note;r.confirmedAt=new Date().toLocaleString('zh-CN');save();close();toast(`${decision} 已记录`);return}
if(f.id==='knowledge-form'){let kb=data.knowledge.find(x=>x.id===v.get('baseId')&&x.space==='企业私有'),file=f.elements.namedItem('document')?.files[0],manual=v.get('content').trim();if(!kb){toast('请选择企业知识库');return}if(file&&!/\.(md|txt|csv|json)$/i.test(file.name)){toast('请选择 .md、.txt、.csv 或 .json 文本文件');return}if(file&&file.size>256*1024){toast('文件超过 256 KB，请选择更小的文本文件');return}if(!file&&!manual){toast('请选择文件或直接填写文档内容');return}const complete=content=>{let title=v.get('title').trim()||file?.name||'未命名文档',doc={id:'d'+Date.now(),title,fileName:file?.name||'手动录入',format:file?file.name.split('.').pop().toUpperCase():'文本',content,status:'待审核',version:'v0.1',author:'张管理员',updated:new Date().toLocaleDateString('zh-CN')};kb.documents??=[];kb.documents.unshift(doc);kb.updated=doc.updated;save();go('knowledge-base',kb.id+'/'+doc.id);toast('文档已上传为待审核版本')};if(file){file.text().then(complete).catch(()=>toast('文件读取失败，请重试'))}else complete(manual);return}
if(f.id==='skill-form'){let a=data.agents.find(x=>x.id===id),pkg;try{pkg=JSON.parse(v.get('skill'))}catch{toast('JSON 结构无效');return}let keys=['name','inputs','steps','rules','tools','output'];if(keys.some(k=>pkg[k]===undefined)){toast('结构缺项：需包含 name、inputs、steps、rules、tools、output');return}if(!Array.isArray(pkg.tools)||[...pkg.tools].sort().join('|')!==[...a.tools].sort().join('|')){toast('Skill 包不能修改由官方发布的 MCP 数据依赖');return}if(JSON.stringify(pkg).match(/"(script|eval|javascript|code)"\s*:/i)){toast('导入受阻：首版不接受任意执行代码');return}preserveLive(a);a.skill=pkg.name;a.skillVersion=`v${Date.now().toString().slice(-4)}-企业版`;a.checks=false;a.tested=false;if(!a.live)a.status='草稿';save();close();toast('企业私有 Skill 已导入，需重新测试发布');return}
if(f.id==='source-form'){let m=data.mappings[+id];m.source=v.get('source');m.domain=v.get('domain');save();close();toast(`${m.store}的${m.domain}主来源已保存`);return}
if(f.id==='delete-form'){data.deletions.push({scope:v.get('scope'),reason:v.get('reason'),state:'待人工处理'});save();close();toast('删除申请已记录，等待平台人工处理');return}
if(f.id==='rule-form'){let r={id:'r'+Date.now(),name:v.get('name').trim(),agent:v.get('agent'),store:v.get('store'),schedule:v.get('schedule'),owner:v.get('owner'),reviewer:v.get('reviewer'),status:'运行中',last:'—'};data.rules.unshift(r);save();close();toast('定时规则已创建');return}
if(f.id==='employee-form'){let e=data.employees[+id];e.menus=v.get('menus').trim();e.agents=v.get('agents').trim();e.stores=v.get('stores');save();close();toast('员工权限已更新');return}
if(f.id==='add-model-form'){let name=v.get('name').trim(),provider=v.get('provider').trim(),key=v.get('apiKey').trim();if(!provider||!name||!key){toast('请完整填写供应商、API Key 和模型名称');return}if(f.dataset.tested!=='true'){toast('请先执行演示检查连接');return}if(data.models.some(m=>m.name===name)){showFieldError(f,'name','模型名称已存在');return}data.models.push({id:'model-'+Date.now(),name,provider,status:'连接正常（演示）',scope:'未批准发送业务数据',approved:[],keyConfigured:true});save();close();toast('模型已添加；请设置 Agent 与数据发送范围');return}
