document.addEventListener('input',ev=>{if(ev.target.closest('#erp-credential-form')){let f=ev.target.form;f.dataset.tested='false';let result=$('#erp-credential-test');if(result)result.textContent='输入已更改，请重新检查填写。'}if(ev.target.closest('#add-model-form')&&['apiKey','name'].includes(ev.target.name)){let f=ev.target.form;f.dataset.tested='false';let result=$('#model-test-result');if(result){result.textContent='输入已更改，请重新执行演示检查。';result.classList.remove('ok')}}if(ev.target.id==='global-search-input'){let results=$('#global-search-results');if(results)results.innerHTML=searchResults(ev.target.value)}if(ev.target.getAttribute('aria-invalid')==='true'){ev.target.removeAttribute('aria-invalid');ev.target.removeAttribute('aria-describedby');ev.target.closest('.field')?.querySelector('.field-error')?.remove()}});
document.addEventListener('change',ev=>{if(ev.target.matches('.input-param-type')){let row=ev.target.closest('.input-param-row'),label=row.querySelector('[name=inputLabel]'),key=row.querySelector('[name=inputKey]');if(ev.target.value==='store-multi'){label.value='店铺';key.value='stores';label.readOnly=true}else if(ev.target.value==='product-multi'){label.value='产品';key.value='products';label.readOnly=true}else{label.value='';key.value='';label.readOnly=false;label.focus()}return}if(ev.target.matches('[data-run-filter]')){runFilters.keyword=$('#run-keyword')?.value.trim()||runFilters.keyword;runFilters[ev.target.dataset.runFilter]=ev.target.value;runsPageNumber=1;render();return}if(ev.target.matches('[data-sync-filter]')){syncFilters[ev.target.dataset.syncFilter]=ev.target.value;syncPage=1;render();return}if(ev.target.matches('[data-mapping-filter]')){mappingFilters[ev.target.dataset.mappingFilter]=ev.target.value;mappingFilters.keyword=document.querySelector('#mapping-filter-form [name=keyword]')?.value.trim()??mappingFilters.keyword;mappingPage=1;render();return}if(ev.target.name==='knowledge'&&ev.target.closest('.knowledge-dropdown')){let dropdown=ev.target.closest('.knowledge-dropdown'),count=dropdown.querySelectorAll('input[name=knowledge]:checked').length;dropdown.querySelector('.knowledge-summary').textContent=count?`已选择 ${count} 个知识库`:'选择已发布知识库'}if(ev.target.closest('#add-model-form')&&ev.target.name==='provider'){let f=ev.target.form;f.dataset.tested='false';let result=$('#model-test-result');if(result){result.textContent='供应商已更改，请重新执行演示检查。';result.classList.remove('ok')}}if(ev.target.id==='decision'){let q=$('#final-qty');if(q){q.disabled=ev.target.value==='驳回';if(ev.target.value==='驳回')q.value=0}}});
window.addEventListener('hashchange',render);document.addEventListener('keydown',ev=>{if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();if(!modal){focusReturn={action:'global-search',id:''};modal={type:'global-search',id:''};render();$('#global-search-input')?.focus()}return}if(ev.key==='Escape'&&modal){close();return}if(ev.key==='Tab'&&modal){let d=document.querySelector('.modal');if(!d)return;let list=[...d.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.getClientRects().length);if(!list.length)return;let first=list[0],last=list.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus()}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus()}}});render();
